const items = $input.all();
const emails = items.map(function (i) {
  const j = i.json || {};
  const h = j.headers || {};
  return {
    from: j.From || h.From || 'unknown sender',
    subject: j.Subject || h.Subject || '(no subject)',
    date: j.Date || h.Date || j.internalDate || '',
    snippet: String(j.snippet || '').slice(0, 300),
    labels: j.labelIds || []
  };
});
return [{ json: { emailCount: emails.length, emails: emails } }];

const items = $input.all();
const events = items.map(function (i) {
  const j = i.json || {};
  const start = (j.start && (j.start.dateTime || j.start.date)) || '';
  const end = (j.end && (j.end.dateTime || j.end.date)) || '';
  return {
    summary: j.summary || '(no title)',
    start: start,
    end: end,
    location: j.location || '',
    attendees: Array.isArray(j.attendees) ? j.attendees.length : 0,
    meetLink: j.hangoutLink || '',
    description: String(j.description || '').slice(0, 300)
  };
});
events.sort(function (a, b) { return String(a.start).localeCompare(String(b.start)); });
return [{ json: { eventCount: events.length, events: events } }];

const raw = String($json.output || '').trim();
const isHtml = /<!doctype\s+html/i.test(raw) || /<html[\s>]/i.test(raw);
let html = raw;
if (!isHtml) {
  const body = raw.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>Daily Briefing</title><style>body{margin:0;padding:40px;background:#0f172a;color:#e2e8f0;font-family:Segoe UI,Arial,sans-serif}h1{color:#38bdf8;font-weight:600}pre{white-space:pre-wrap;font-family:inherit;font-size:15px;line-height:1.6;background:#1e293b;padding:24px;border-radius:12px}</style></head><body><h1>Daily Briefing</h1><pre>' + body + '</pre></body></html>';
}
return [{ json: { html: html, generatedAt: new Date().toISOString(), source: 'briefing-director-agent' } }];
